/**
 * The values Storybook's manager (sidebar, toolbar) needs, read from the built tokens.
 *
 * The manager runs in its own document, so it cannot read custom properties; it gets resolved
 * values instead. They come from `dist/tokens.ts`, generated by `npm run tokens`, and are never
 * typed in by hand. `test/storybook-theme.test.mjs` fails when a value here stops matching a token.
 * No Storybook import on purpose: the test loads this file alone. Plain JS so Node 20+ can load it
 * without TypeScript.
 *
 * @param {typeof import('../dist/tokens').tokens} t
 */
export function managerValues(t) {
  return {
    colorPrimary: t.action.primary,
    colorSecondary: t.action.primary,

    appBg: t.surface.sunken,
    appContentBg: t.surface.default,
    appPreviewBg: t.surface.default,
    appHoverBg: t.state['hover-layer'],
    appBorderColor: t.border.default,
    appBorderRadius: Number.parseInt(t.radius.md, 10),

    fontBase: t.font.sans,
    fontCode: t.font.mono,

    textColor: t.text.default,
    textInverseColor: t.text.inverse,
    textMutedColor: t.text.muted,

    barBg: t.surface.default,
    barTextColor: t.text.muted,
    barHoverColor: t.action.primary,
    barSelectedColor: t.action.primary,

    buttonBg: t.surface.default,
    buttonBorder: t.border.default,
    booleanBg: t.surface.sunken,
    booleanSelectedBg: t.surface.default,

    inputBg: t.surface.default,
    inputBorder: t.border.strong,
    inputTextColor: t.text.default,
    inputBorderRadius: Number.parseInt(t.radius.control, 10),
  };
}

/**
 * The tokens as one theme sees them: the default values with that theme's own laid over.
 *
 * @template T
 * @param {T} base
 * @param {object} [overrides]
 * @returns {T}
 */
export function withTheme(base, overrides = {}) {
  const merged = { ...base };
  for (const [key, value] of Object.entries(overrides)) {
    const isGroup = value && typeof value === 'object' && base?.[key] && typeof base[key] === 'object';
    merged[key] = isGroup ? withTheme(base[key], value) : value;
  }
  return merged;
}
